"use client";

import { cn } from "../lib/cn";
import { Menu, MenuContent, MenuItem, MenuTrigger } from "../menu/menu";
import { DownloadIcon } from "./chart-icons";
import type { ChartCardLabels } from "./chart-parts";
import type { ChartExportFormat } from "./chart-export";

/*
 * The chart card's download menu. It lives in its own file so ChartCard can load it lazily:
 * Base UI's Menu (positioner, floating-ui, list navigation) is ~45 KB gzip, and a chart page
 * shows only a small icon button until somebody opens it.
 */

/**
 * Props of ChartExportMenu: the card title, the formats to offer, whether CSV is included, `labels`
 * and the `onExport` handler.
 */
export type ChartExportMenuProps = {
  title: string;
  labels: ChartCardLabels;
  formats: readonly ChartExportFormat[];
  /** The CSV item shows only when there is data to export. */
  csv: boolean;
  onExport: (format: ChartExportFormat) => void;
};

export default function ChartExportMenu({ title, labels: t, formats, csv, onExport }: ChartExportMenuProps) {
  return (
    <Menu>
      <MenuTrigger
        aria-label={t.options(title)}
        className={cn(
          "relative inline-flex size-8 items-center justify-center rounded-sheen-full text-sheen-fg-muted transition-colors duration-(--sheen-duration-fast)",
          "hover:bg-sheen-hover hover:text-sheen-fg data-popup-open:bg-sheen-hover data-popup-open:text-sheen-fg",
          "focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
          "any-pointer-coarse:after:absolute any-pointer-coarse:after:-inset-1.5",
        )}
      >
        <DownloadIcon />
      </MenuTrigger>
      <MenuContent align="end">
        {formats.includes("png") && (
          <MenuItem description={t.pngHint} onClick={() => onExport("png")}>
            {t.downloadPng}
          </MenuItem>
        )}
        {formats.includes("svg") && (
          <MenuItem description={t.svgHint} onClick={() => onExport("svg")}>
            {t.downloadSvg}
          </MenuItem>
        )}
        {formats.includes("csv") && csv && (
          <MenuItem description={t.csvHint} onClick={() => onExport("csv")}>
            {t.downloadCsv}
          </MenuItem>
        )}
      </MenuContent>
    </Menu>
  );
}

export { type ChartSeriesState, useChartSeriesState, useChartSeriesVisibility } from "./chart-parts/state";
export {
  type LegendItem,
  type ChartLegendLabels,
  defaultChartLegendLabels,
  type ChartLegendProps,
  ChartLegend,
  LegendKey,
  seriesLegend,
  type TooltipRow,
  type TooltipSurface,
  chartTooltipSurface,
  type ChartTooltipProps,
  ChartTooltip,
  ChartAnnouncer,
} from "./chart-parts/legend-tooltip";
export {
  useChartSharedLabels,
  ChartEmpty,
  defaultChartTableLabels,
  type ChartTableLabels,
  ChartTable,
} from "./chart-parts/empty-table";
export {
  type ChartCardLabels,
  defaultChartCardLabels,
  type ChartCardProps,
  ChartCard,
  type ChartTableProps,
  type ChartAnnouncerProps,
  type ChartEmptyProps,
  type LegendKeyProps,
} from "./chart-parts/chart-card";

"use client";

import type { ComponentProps } from "react";
import {
  Suspense,
  startTransition,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { flushSync } from "react-dom";
import { Tabs as BaseTabs } from "@base-ui/react/tabs";

import { cn } from "../../lib/cn";
import { HEADING_TAGS, headingBelow, type HeadingLevelOption } from "../../lib/heading";
import { Skeleton } from "../../skeleton/skeleton";
import {
  chartCsv,
  chartFileName,
  downloadCsv,
  exportChartImage,
  tableCsv,
  type ChartCsvOptions,
  type ChartExportFormat,
} from "../chart-export";
import { ChartTwinContext } from "../chart-figure";
import { useChartSeriesState, ChartExportMenu, type SeriesContextValue, SeriesContext } from "./state";
import {
  type LegendItem,
  type ChartLegendLabels,
  defaultChartLegendLabels,
  ChartLegend,
  LegendKey,
  ChartAnnouncer,
} from "./legend-tooltip";
import { ChartEmpty, ChartTable, LabelsContext, TableLabelContext } from "./empty-table";

/* ---------- Chart card ---------- */

/**
 * Translatable text of ChartCard: tab names, export menu items, download announcements and the legend
 * strings.
 */
export type ChartCardLabels = {
  /** Tab names. */
  chart: string;
  table: string;
  /** Spoken name of the loading placeholder shown while `loading` is true. */
  loading: string;
  /** Name of the Chart / Table tab list. */
  viewAs: (title: string) => string;
  /** Name of the screen-reader copy of the data table. */
  dataTable: (title: string) => string;
  /** Empty table / empty chart text inside this card. */
  noData: ReactNode;
  /** Header of previous-period table columns. */
  previous: (label: string) => string;
  /** The export menu button's accessible name. */
  options: (title: string) => string;
  downloadPng: string;
  downloadSvg: string;
  downloadCsv: string;
  /** Second lines of the menu items. */
  pngHint: string;
  svgHint: string;
  csvHint: string;
  /** Announced after a download starts. */
  downloaded: (file: string) => string;
  exportFailed: string;
} & ChartLegendLabels;

/**
 * The built-in English strings of ChartCard; spread it into your own `labels` and change what you
 * need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultChartCardLabels: ChartCardLabels = {
  chart: "Chart",
  table: "Table",
  loading: "Loading chart",
  viewAs: (title) => `${title}: view as`,
  dataTable: (title) => `${title} data table`,
  noData: "No data",
  previous: (label) => `${label} (previous)`,
  options: (title) => `${title}: download`,
  downloadPng: "Download PNG",
  downloadSvg: "Download SVG",
  downloadCsv: "Download CSV",
  pngHint: "Image, 2× resolution",
  svgHint: "Vector, for slides and docs",
  csvHint: "The data, for spreadsheets",
  downloaded: (file) => `Downloaded ${file}`,
  exportFailed: "Download failed",
  ...defaultChartLegendLabels,
};

/** Props of ChartCard: title, the chart and its table view, legend, export menu and `labels`. */
export type ChartCardProps = {
  /** Sets the card's heading text. */
  title: string;
  /** A line of context under the title (period, unit, source). */
  description?: ReactNode;
  /** Shown at the top right, e.g. a headline number. */
  aside?: ReactNode;
  /** Legend shown under the header. Omit for single-series charts (the title names the series). */
  legend?: readonly LegendItem[];
  /** Table view of the same data. When given, the card gets Chart / Table tabs. */
  table?: ReactNode;
  /** Heading level of the title (1 to 6, default 3), to fit the page outline, or `"none"` for a paragraph with no heading role (for an example). */
  headingLevel?: HeadingLevelOption;
  /** The chart (or table) the card frames; it fills the card body under the title and description. */
  children: ReactNode;
  /** Adds extra classes to the card's outer element. */
  className?: string;
  /**
   * Interactive legend: when the chart inside supports it (Line, Area, Bar, Donut), legend
   * items become toggle buttons that hide / show a series. Default true; false keeps it static.
   */
  legendToggle?: boolean;
  /** Hides these series at first (interactive legends). */
  defaultHiddenSeries?: readonly string[];
  /**
   * A download menu: PNG / SVG of the chart (colours resolved, exactly as shown) and CSV of the
   * data. `true` offers every format; or pick some, and name the file (default: the title).
   */
  exportable?: boolean | { formats?: ChartExportFormat[]; filename?: string };
  /** Data for the CSV download. Without it the CSV is read from the table view. */
  csv?: ChartCsvOptions;
  /** The card's built-in strings (tab names, CSV button, table text); a partial object over the English defaults, so pass only the keys you translate. */
  labels?: Partial<ChartCardLabels>;
  /**
   * "glass" (default): a glass-2 card. "plain": the same card without backdrop blur, for cards
   * nested inside another glass panel or many cards in view at once (the glass budget).
   */
  surface?: "glass" | "plain";
  /** Show a skeleton placeholder instead of the chart (and the table) while data is on its way. Default false. */
  loading?: boolean;
};

/** The glass card classes of a chart with a header. @internal */
export const cardClass = "glass-2 flex min-w-0 flex-col gap-4 rounded-sheen-lg p-5";
/** The plain card classes of a chart without glass. @internal */
export const plainCardClass =
  "flex min-w-0 flex-col gap-4 rounded-sheen-lg border border-sheen-border bg-sheen-surface/55 p-5 shadow-[inset_0_1px_0_0_var(--sheen-glass-highlight)] forced-colors:border-[CanvasText]";
/* Compact view tabs. On touch screens an invisible ::before grows each hit area to 44px tall. */
/** The class string of a compact view tab, with a 44px touch hit area. @internal */
export const viewTabClass = cn(
  "relative z-10 inline-flex h-7 items-center justify-center rounded-sheen-full px-3 text-xs font-medium whitespace-nowrap text-sheen-fg-muted select-none",
  "transition-[color] duration-(--sheen-duration-fast) hover:text-sheen-fg data-active:text-sheen-fg",
  "touch-manipulation [-webkit-tap-highlight-color:transparent]",
  "focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
  "sheen-hit-before",
  "forced-colors:data-active:underline forced-colors:data-active:decoration-2 forced-colors:data-active:underline-offset-4",
);
// `flex-1 justify-end`: in a row of cards of unequal content (one has a legend row, one a donut) the plots sit on the card's bottom edge, so their baselines line up across the row.
/** The inner panel classes of a chart card. @internal */
export const panelClass =
  "flex min-w-0 flex-1 flex-col justify-end gap-4 rounded-sheen-sm outline-none " +
  "focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus";

/**
 * A glass card with header, legend and (when `table` is given) Chart / Table tabs.
 * The tabs control real tab panels, so assistive tech hears "Chart, tab 1 of 2" and lands in
 * the matching panel. Switching is cheap: both panels stay mounted once shown (the chart is
 * never torn down and re-drawn), a visually hidden copy of the table keeps the data in the accessibility tree while the chart shows (the figure's `aria-details` points at it), the table tab is built the first time it's wanted (or when the
 * pointer heads for its tab), and the active pill moves with a transform, never a measurement.
 *
 * Keyboard: Tab reaches the Chart / Table tabs (arrow keys switch them), the interactive legend (Enter or Space toggles a series) and the download menu. Reading a point inside the chart is each chart's own arrow-key behaviour.
 * Glass and motion: one glass-2 surface (`surface="plain"` drops the blur). The tab pill moves with a transform; reduced motion makes it instant. The table view is the colour-free, screen-reader view of the same data.
 *
 * @example
 * ```tsx
 * import { ChartCard, ChartTable, LineChart, seriesLegend, type ChartSeries } from "@sheenui/theme";
 *
 * const series: ChartSeries[] = [{ key: "v", label: "Visits" }];
 * const rows = [
 *   { m: "Jan", v: 4 },
 *   { m: "Feb", v: 7 },
 * ];
 *
 * export function Example() {
 *   return (
 *     <ChartCard title="Visits" description="Last two months" legend={seriesLegend(series, "line")} table={<ChartTable data={rows} index="m" series={series} caption="Visits per month" />} exportable>
 *       <LineChart data={rows} index="m" series={series} aria-label="Visits per month" />
 *     </ChartCard>
 *   );
 * }
 * ```
 *
 * @see /charts
 */
export function ChartCard({
  title,
  description,
  aside,
  legend,
  table,
  headingLevel = 3,
  children,
  className,
  legendToggle = true,
  defaultHiddenSeries,
  exportable = false,
  csv,
  labels,
  surface = "glass",
  loading = false,
}: ChartCardProps) {
  const Heading = HEADING_TAGS[headingBelow(headingLevel, 0)];
  const surfaceClass = surface === "plain" ? plainCardClass : cardClass;
  const t = { ...defaultChartCardLabels, ...labels };
  const [view, setView] = useState<string>("chart");
  const [tableMounted, setTableMounted] = useState(false);
  // While the table is still being built (in a transition), the empty panel keeps the card at
  // the chart's height, so switching never collapses and re-grows the card.
  const [holdHeight, setHoldHeight] = useState(0);
  const titleId = useId();
  const tableId = useId();
  const twinId = useId();
  // The Table tab's panel is display:none while the chart shows, so it is out of the accessibility tree. A visually hidden
  // copy of the table (built after first paint) keeps the data reachable through the figure's aria-details at all times.
  const [twinReady, setTwinReady] = useState(false);
  useEffect(() => {
    if (table) startTransition(() => setTwinReady(true));
  }, [table]);
  const chartPanel = useRef<HTMLDivElement>(null);
  const tablePanel = useRef<HTMLDivElement>(null);
  const [announcement, setAnnouncement] = useState("");

  // Series visibility shared with the chart inside.
  const series = useChartSeriesState(defaultHiddenSeries);
  const [registered, setRegistered] = useState(0);
  const register = useCallback(() => {
    setRegistered((n) => n + 1);
    return () => setRegistered((n) => n - 1);
  }, []);
  const seriesContext = useMemo<SeriesContextValue>(() => ({ ...series, register }), [series, register]);
  const shared = useMemo(
    () => ({ noData: labels?.noData, previous: labels?.previous }),
    [labels?.noData, labels?.previous],
  );

  const toggleable = legendToggle && registered > 0;
  const legendEl =
    legend && legend.length > 1 ? (
      toggleable ? (
        <ChartLegend
          items={legend}
          hidden={series.hidden}
          onToggle={series.toggle}
          onHighlight={series.setHighlighted}
          labels={{ legend: t.legend, shown: t.shown, hidden: t.hidden }}
        />
      ) : (
        <ChartLegend items={legend} />
      )
    ) : null;

  const formats: ChartExportFormat[] = exportable
    ? exportable === true
      ? ["png", "svg", "csv"]
      : (exportable.formats ?? ["png", "svg", "csv"])
    : [];
  const named = typeof exportable === "object" ? exportable.filename : undefined;
  const fileBase = chartFileName(named !== undefined && named !== "" ? named : title);

  async function runExport(format: ChartExportFormat) {
    try {
      if (format === "csv") {
        let text = csv ? chartCsv(csv) : "";
        if (!text && table) {
          // The table view is the source of truth: build it now if it hasn't been shown yet.
          if (!tableMounted) flushSync(() => setTableMounted(true));
          const el = tablePanel.current?.querySelector("table");
          if (el) text = tableCsv(el);
        }
        if (!text) throw new Error("no data");
        downloadCsv(fileBase, text);
        setAnnouncement(t.downloaded(`${fileBase}.csv`));
      } else {
        const ok = await exportChartImage(chartPanel.current, format, fileBase, { title });
        if (!ok) throw new Error("no chart");
        setAnnouncement(t.downloaded(`${fileBase}.${format}`));
      }
    } catch {
      setAnnouncement(t.exportFailed);
    }
  }

  const menu =
    formats.length > 0 ? (
      // The server renders the real menu button; the fallback only shows on a client-side
      // navigation, and holds the button's box so the header does not shift.
      <Suspense fallback={<span aria-hidden className="inline-block size-8" />}>
        <ChartExportMenu
          title={title}
          labels={t}
          formats={formats}
          csv={!!csv || !!table}
          onExport={(format) => void runExport(format)}
        />
      </Suspense>
    ) : null;

  const tabs = table ? (
    <BaseTabs.List
      aria-label={t.viewAs(title)}
      // Two views: arrowing between them switches at once (automatic activation), as the
      // keyboard docs promise. The table is built in a transition, so the switch stays instant.
      activateOnFocus
      className="relative grid grid-cols-2 rounded-sheen-full bg-sheen-hover p-0.5 shadow-[inset_0_0_0_1px_var(--sheen-border)]"
    >
      {/* The active pill: half the track, moved by a transform (no measuring, no layout). */}
      <span
        aria-hidden
        data-slot="chart-view-pill"
        className={cn(
          "pointer-events-none absolute inset-y-0.5 left-0.5 w-[calc(50%-2px)] rounded-sheen-full bg-sheen-indicator shadow-(--sheen-indicator-shadow)",
          "motion-ok:transition-transform motion-ok:duration-(--sheen-duration-snappy) motion-ok:ease-sheen-snappy",
          "forced-colors:hidden",
        )}
        style={{ transform: view === "table" ? "translateX(100%)" : "translateX(0)" }}
      />
      <BaseTabs.Tab value="chart" className={viewTabClass}>
        {t.chart}
      </BaseTabs.Tab>
      <BaseTabs.Tab
        value="table"
        className={viewTabClass}
        // Build the table as soon as the pointer or focus heads for its tab, in a transition
        // that yields to input: by the time it's clicked, switching only flips visibility.
        onPointerEnter={() => !tableMounted && startTransition(() => setTableMounted(true))}
        onFocus={() => !tableMounted && startTransition(() => setTableMounted(true))}
      >
        {t.table}
      </BaseTabs.Tab>
    </BaseTabs.List>
  ) : null;

  const header = (
    <header className="flex flex-wrap items-start justify-between gap-3">
      <div className="min-w-0">
        <Heading id={titleId} className="font-semibold">
          {title}
        </Heading>
        {description && <p className="mt-0.5 text-sm text-sheen-fg-muted">{description}</p>}
      </div>
      {(!!aside || !!tabs || !!menu) && (
        <div className="flex items-center gap-2">
          {aside && <div className="me-1">{aside}</div>}
          {tabs}
          {menu}
        </div>
      )}
    </header>
  );

  // While loading, a skeleton stands in for the chart: a polite status, the card keeps a chart-sized height.
  const content = loading ? (
    <div role="status" aria-busy="true" className="flex flex-col gap-3">
      <span className="sr-only">{t.loading}</span>
      <Skeleton shape="rect" height={192} className="w-full" />
      <Skeleton shape="text" width="40%" />
    </div>
  ) : (
    children
  );

  const body = !table ? (
    <section aria-labelledby={titleId} className={cn(surfaceClass, className)}>
      {header}
      {legendEl}
      <div ref={chartPanel} className="flex min-w-0 flex-1 flex-col justify-end gap-4">
        {content}
      </div>
      {menu && <ChartAnnouncer text={announcement} />}
    </section>
  ) : (
    <BaseTabs.Root
      value={view}
      onValueChange={(v) => {
        const next = String(v);
        // The switch itself is instant (the pill moves, the panels swap). A table that hasn't
        // been built yet is rendered in a transition, which yields to input instead of
        // blocking the tap in one long task (on touch screens there's no hover to pre-build it).
        setView(next);
        if (next === "table" && !tableMounted) {
          setHoldHeight(chartPanel.current?.offsetHeight ?? 0);
          startTransition(() => setTableMounted(true));
        }
      }}
      render={<section aria-labelledby={titleId} />}
      className={cn(surfaceClass, className)}
    >
      {header}
      {/* The chart itself is focusable, so its panel isn't a separate tab stop. */}
      <BaseTabs.Panel ref={chartPanel} value="chart" keepMounted tabIndex={-1} className={panelClass}>
        {legendEl}
        {content}
      </BaseTabs.Panel>
      <BaseTabs.Panel
        ref={tablePanel}
        id={tableId}
        value="table"
        keepMounted
        aria-busy={!tableMounted || undefined}
        className={panelClass}
        style={tableMounted || holdHeight <= 0 ? undefined : { minHeight: holdHeight }}
      >
        {tableMounted ? table : null}
      </BaseTabs.Panel>
      {twinReady && view === "chart" ? (
        <div id={twinId} className="sr-only">
          <TableLabelContext value={t.dataTable(title)}>{table}</TableLabelContext>
        </div>
      ) : null}
      {menu && <ChartAnnouncer text={announcement} />}
    </BaseTabs.Root>
  );

  return (
    <SeriesContext value={seriesContext}>
      <LabelsContext value={shared}>
        <ChartTwinContext value={table ? (twinReady && view === "chart" ? twinId : tableId) : null}>
          {body}
        </ChartTwinContext>
      </LabelsContext>
    </SeriesContext>
  );
}

/** Props of {@link ChartTable}. Every chart has a table view: the accessible, colour-free way to read every value. */
export type ChartTableProps = ComponentProps<typeof ChartTable>;

/** Props of {@link ChartAnnouncer}. Screen-reader announcement of the active data point (charts are keyboard-navigable). */
export type ChartAnnouncerProps = ComponentProps<typeof ChartAnnouncer>;

/** Props of {@link ChartEmpty}. Shown instead of a chart when there is nothing to plot. */
export type ChartEmptyProps = ComponentProps<typeof ChartEmpty>;

/** Props of {@link LegendKey}. The colour key for a series, drawn as SVG (not a CSS background) so it survives forced-colors / Windows High Contrast, where it also gains a CanvasText outline. */
export type LegendKeyProps = ComponentProps<typeof LegendKey>;

"use client";

import { createContext, useContext, useEffect, useState, type ReactNode } from "react";

import { cn } from "../../lib/cn";
import { formatCompact, num, seriesColor, type ChartRow, type CompareSeries } from "../chart-utils";
import { LegendKey } from "./legend-tooltip";

/* ---------- Shared labels (i18n) ---------- */

/** The labels every chart shares, such as the no-data text. @internal */
export type SharedLabels = { noData: ReactNode; previous: (label: string) => string };
/** Supplies shared chart labels to every chart below a provider. @internal */
export const LabelsContext = createContext<Partial<SharedLabels> | null>(null);

/**
 * Text a ChartCard hands down to its table and empty states (labels.noData, labels.previous).
 *
 * Returns `{ noData, previous }`, the strings a ChartCard's `labels` hand down (defaults "No data" and "<series> (previous)"). Use it in custom charts so they speak the card's language.
 * Not a component: no DOM, keyboard or screen-reader behaviour of its own.
 *
 * @example
 * ```tsx
 * import { useChartSharedLabels } from "@sheenui/theme";
 *
 * function Empty() {
 *   const { noData } = useChartSharedLabels();
 *   return <p>{noData}</p>;
 * }
 * ```
 *
 * @see /charts
 */
export function useChartSharedLabels(): SharedLabels {
  const ctx = useContext(LabelsContext);
  return {
    noData: ctx?.noData ?? defaultChartTableLabels.noData,
    previous: ctx?.previous ?? defaultChartTableLabels.previous,
  };
}

/* ---------- Empty state ---------- */

/**
 * Shown instead of a chart when there is nothing to plot. Keeps the chart's footprint (so
 * layouts don't jump) and stays readable to screen readers: "<label>: No data".
 * The default text comes from the enclosing ChartCard's `labels.noData` ("No data").
 *
 * Props: `height` (px, keeps the chart's footprint), `aria-label` (names the chart; required), `children` (message; default the card's "No data") and `className`.
 * Accessibility: a `role="group"` named like the chart, so screen readers hear "Revenue: No data". Static (no motion).
 *
 * @example
 * ```tsx
 * import { ChartEmpty } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <ChartEmpty height={160} aria-label="Revenue per month">
 *       No sales yet
 *     </ChartEmpty>
 *   );
 * }
 * ```
 *
 * @see /charts/edge-cases
 */
export function ChartEmpty({
  height,
  "aria-label": ariaLabel,
  children,
  className,
}: {
  /** Height of the empty state in px, so the layout does not jump when data arrives. */
  height: number;
  /** Sets the accessible name of the empty chart. */
  "aria-label": string;
  children?: ReactNode;
  className?: string;
}) {
  const shared = useChartSharedLabels();
  return (
    <div
      role="group"
      aria-roledescription="chart"
      aria-label={ariaLabel}
      data-slot="chart-empty"
      className={cn("relative flex w-full items-center justify-center", className)}
      style={{ height }}
    >
      {/* Faint, decorative grid so the empty card still reads as a chart. */}
      <svg aria-hidden className="absolute inset-0 size-full" preserveAspectRatio="none">
        {[0.2, 0.45, 0.7].map((t) => (
          <line key={t} x1="0" x2="100%" y1={`${t * 100}%`} y2={`${t * 100}%`} stroke="var(--sheen-chart-grid)" />
        ))}
        <line x1="0" x2="100%" y1="92%" y2="92%" stroke="var(--sheen-border)" />
      </svg>
      <p className="relative text-sm text-sheen-fg-muted">{children ?? shared.noData}</p>
    </div>
  );
}

/* ---------- Table view ---------- */

/**
 * Translatable text of ChartTable (`noData`, `previous(label)`), usually handed down by the enclosing
 * ChartCard.
 */
export type ChartTableLabels = {
  /** Shown when there are no rows. */
  noData: ReactNode;
  /** Header of a previous-period column. */
  previous: (label: string) => string;
};

/** The English strings of `ChartTable` (and of the empty state); a `ChartCard`'s `labels` override them below it. */
export const defaultChartTableLabels: ChartTableLabels = {
  noData: "No data",
  previous: (label: string) => `${label} (previous)`,
};

/**
 * Set only inside a ChartCard's screen-reader twin (the visually hidden copy of the table view): the name of the
 * twin's table. Table scrollers read it to stay static named blocks there (TableOverflow, TableScroll, ChartValueTable).
 * @internal
 */
export const TableLabelContext = createContext<string | null>(null);

/** A horizontally scrolling wrapper that becomes a focusable group only while it overflows. */
export function TableOverflow({ label: ownLabel, children }: { label?: string; children: ReactNode }) {
  const twinLabel = useContext(TableLabelContext);
  const label = twinLabel ?? ownLabel;
  const [el, setEl] = useState<HTMLDivElement | null>(null);
  const [overflow, setOverflow] = useState(false);
  useEffect(() => {
    if (!el) return;
    // Measured from the ResizeObserver's own (post-layout) notifications, including the first
    // one: reading scrollWidth here would force a layout inside the table's commit.
    const update = () => setOverflow(el.scrollWidth - el.clientWidth > 1);
    const ro = new ResizeObserver(update);
    ro.observe(el);
    if (el.firstElementChild) ro.observe(el.firstElementChild);
    return () => ro.disconnect();
  }, [el]);
  // In the twin (a 1 px hidden box) every table "overflows": a static named block there, never an invisible tab stop.
  if (twinLabel !== null)
    return (
      <div role="group" aria-label={label}>
        {children}
      </div>
    );
  return (
    <div
      ref={setEl}
      // A named group, not a region landmark: it would repeat the name of the chart card around it (see TableScroll).
      role={overflow ? "group" : undefined}
      aria-label={overflow ? label : undefined}
      // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- a scrollable region that can overflow must be keyboard-focusable (WCAG 2.1.1 keyboard)
      tabIndex={overflow ? 0 : undefined}
      className="overflow-x-auto rounded-sheen-sm outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus"
    >
      {children}
    </div>
  );
}

/**
 * Every chart has a table view: the accessible, colour-free way to read every value.
 * Series with a `compareKey` get a previous-period column too.
 *
 * Props: `data`, `index` (the row key), `series`, `format` (default compact numbers), `indexLabel` (first column header), `caption` (hidden, names the table) and `labels` ({ noData, previous }).
 * Accessibility: a real `<table>` with a caption and header cells, so values are readable without colour or pointer. It scrolls inside its own focusable region when wider than the card. Static (no motion).
 *
 * @example
 * ```tsx
 * import { ChartTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <ChartTable data={[{ m: "Jan", v: 4 }, { m: "Feb", v: 7 }]} index="m" series={[{ key: "v", label: "Visits" }]} indexLabel="Month" caption="Visits per month" />
 *   );
 * }
 * ```
 *
 * @see /charts
 */
export function ChartTable({
  data,
  index,
  series,
  format = formatCompact,
  indexLabel,
  caption,
  labels,
}: {
  /** The rows to show: one object per row, holding the `index` key and one number per series key. */
  data: readonly ChartRow[];
  /** The key in each row that names the row, such as "month". It becomes the first column. */
  index: string;
  /** Series to list as columns; one with a `compareKey` also gets a previous-period column. */
  series: readonly CompareSeries[];
  /** Formats each number in the table cells. */
  format?: (n: number) => string;
  /** Header of the first column; the `index` key when left out. */
  indexLabel?: string;
  /** Visually hidden caption naming the table for screen readers. */
  caption?: string;
  /** Text for i18n (defaults come from the enclosing ChartCard's labels, else English). */
  labels?: Partial<ChartTableLabels>;
}) {
  const shared = useChartSharedLabels();
  const t = { noData: labels?.noData ?? shared.noData, previous: labels?.previous ?? shared.previous };
  const columns = series.flatMap((s, i) => {
    const color = seriesColor(s, i);
    const { compareKey } = s;
    const own = { key: s.key, label: s.label, color, dashed: false };
    return compareKey ? [own, { key: compareKey, label: t.previous(s.label), color, dashed: true }] : [own];
  });
  return (
    <TableOverflow label={caption ?? indexLabel ?? index}>
      <table className="w-full text-start [:where(&)_th]:text-start text-sm">
        {caption && <caption className="sr-only">{caption}</caption>}
        <thead className="text-xs text-sheen-fg-muted">
          <tr className="border-b border-sheen-border">
            <th scope="col" className="py-2 pe-4 font-medium">
              {indexLabel ?? index}
            </th>
            {columns.map((c, i) => (
              <th key={i} scope="col" className="py-2 pe-4 text-end font-medium">
                <span className="inline-flex items-center gap-1.5">
                  <LegendKey color={c.color} dashed={c.dashed} />
                  {c.label}
                </span>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.length === 0 ? (
            <tr>
              <td colSpan={columns.length + 1} className="py-6 text-center text-sheen-fg-muted">
                {t.noData}
              </td>
            </tr>
          ) : (
            data.map((row, ri) => (
              <tr key={ri} className="border-b border-sheen-border last:border-0">
                <th scope="row" className="py-2 pe-4 font-normal text-sheen-fg-muted">
                  {row[index]}
                </th>
                {columns.map((c, ci) => (
                  <td key={ci} className="py-2 pe-4 text-end tabular-nums">
                    {c.dashed && row[c.key] === undefined ? "–" : format(num(row[c.key]))}
                  </td>
                ))}
              </tr>
            ))
          )}
        </tbody>
      </table>
    </TableOverflow>
  );
}

"use client";

import { useEffect, useId, useMemo, useState, type ReactNode } from "react";
import { motion, useSpring } from "motion/react";

import { cn } from "../../lib/cn";
import { useSheenReducedMotion } from "../../hooks/use-preferences";
import { followPointer, seriesColor, type ChartSeries } from "../chart-utils";
import { ChartPatternDefs, patternFill, resolvePatterns } from "../chart-patterns";
import { EMPTY_SET } from "./state";

/* ---------- Legend ---------- */

/**
 * One entry of a ChartLegend: label, colour, key shape, an optional value and the series key it
 * toggles.
 */
export type LegendItem = {
  label: string;
  color: string;
  kind?: "line" | "rect";
  value?: ReactNode;
  /** The series key this item stands for. Needed for an interactive (toggle) legend. */
  key?: string;
  /** Draw the key dashed (a previous-period comparison series). */
  dashed?: boolean;
  /** Hatch pattern index (1 to 8, series position) drawn in the swatch, to match a chart's `patterns`. 0 or unset is solid. */
  pattern?: number;
};

/** Translatable announcements of a ChartLegend (the `labels` prop takes a `Partial` of it). */
export type ChartLegendLabels = {
  /** Name of the legend group when it is interactive. */
  legend: string;
  /** Announced after a series is shown / hidden. */
  shown: (label: string) => string;
  hidden: (label: string) => string;
};

/**
 * The built-in English strings of ChartLegend; spread it into your own `labels` and change what you
 * need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultChartLegendLabels: ChartLegendLabels = {
  legend: "Series: press to show or hide",
  shown: (label) => `${label} shown`,
  hidden: (label) => `${label} hidden`,
};

/**
 * Props of ChartLegend: the items, which keys are hidden, the toggle and highlight handlers, `labels`
 * and `className`.
 */
export type ChartLegendProps = {
  /** The legend keys: one per series, with its label, color and key shape. */
  items: readonly LegendItem[];
  className?: string;
  /** Lists the keys of hidden series (interactive legends). */
  hidden?: ReadonlySet<string> | readonly string[];
  /** Makes items with a `key` toggle buttons. */
  onToggle?: (key: string) => void;
  /** Called with the key under the pointer / focus (null when it leaves): charts dim the others. */
  onHighlight?: (key: string | null) => void;
  /** Overrides for the legend's built-in English strings. */
  labels?: Partial<ChartLegendLabels>;
};

/**
 * Legend keys mirror the mark: a short line for line charts, a swatch for bars/areas. Text stays
 * in text colours. With `onToggle`, each item is a toggle button (aria-pressed = shown):
 * click / Enter / Space hides or shows the series, hover and focus dim the others, and the
 * change is announced.
 *
 * Props: `items` (label, colour, `kind` "line" | "rect", optional `value`, `key`, `dashed`), `hidden` (keys of hidden series), `onToggle` (makes items with a `key` toggle buttons), `onHighlight` (key under the pointer or focus, null on leave), `labels` and `className`.
 * Keyboard: with `onToggle`, Tab moves between items; Enter or Space shows or hides a series. Each button has `aria-pressed`, and the change is announced in a polite live region. Without it the legend is a plain list.
 * Colour keys are SVG, so they survive forced colors; hidden series show a hollow key and struck-through text.
 *
 * @example
 * ```tsx
 * import { ChartLegend } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <ChartLegend
 *       items={[
 *         { label: "Revenue", color: "var(--sheen-chart-1)", kind: "line" },
 *         { label: "Target", color: "var(--sheen-chart-2)", kind: "line", dashed: true },
 *       ]}
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts
 */
export function ChartLegend({ items, className, hidden, onToggle, onHighlight, labels }: ChartLegendProps) {
  const t = { ...defaultChartLegendLabels, ...labels };
  const hiddenSet = useMemo(() => (hidden ? new Set(hidden) : EMPTY_SET), [hidden]);
  const [message, setMessage] = useState("");
  const interactive = Boolean(onToggle) && items.some((i) => i.key !== undefined);

  if (!interactive) {
    return (
      <ul className={cn("flex flex-wrap items-center gap-x-4 gap-y-1.5 text-xs text-sheen-fg-muted", className)}>
        {items.map((item, i) => (
          <li key={i} className="flex items-center gap-1.5">
            <LegendKey color={item.color} kind={item.kind} dashed={item.dashed} pattern={item.pattern} />
            <span>{item.label}</span>
            {item.value !== undefined && <span className="font-semibold text-sheen-fg tabular-nums">{item.value}</span>}
          </li>
        ))}
      </ul>
    );
  }

  return (
    <div
      role="group"
      aria-label={t.legend}
      // Wrapped rows sit 46px apart on touch, so the 44px hit areas of stacked toggles never overlap.
      className={cn(
        "flex flex-wrap items-center gap-x-1 gap-y-1 any-pointer-coarse:gap-y-[1.125rem] text-xs text-sheen-fg-muted",
        className,
      )}
    >
      {items.map((item, i) => {
        const key = item.key;
        if (key === undefined) {
          return (
            <span key={i} className="flex items-center gap-1.5 px-2">
              <LegendKey color={item.color} kind={item.kind} dashed={item.dashed} pattern={item.pattern} />
              <span>{item.label}</span>
            </span>
          );
        }
        const off = hiddenSet.has(key);
        return (
          <button
            key={`${key}\u0000${i}`}
            type="button"
            aria-pressed={!off}
            data-slot="chart-legend-toggle"
            onClick={() => {
              onToggle?.(key);
              setMessage((off ? t.shown : t.hidden)(item.label));
            }}
            onPointerEnter={() => onHighlight?.(off ? null : key)}
            onPointerLeave={() => onHighlight?.(null)}
            onFocus={() => onHighlight?.(off ? null : key)}
            onBlur={() => onHighlight?.(null)}
            className={cn(
              "relative inline-flex h-7 items-center gap-1.5 rounded-sheen-full px-2 select-none",
              "transition-[color,background-color,opacity] duration-(--sheen-duration-fast) hover:bg-sheen-hover hover:text-sheen-fg",
              "touch-manipulation [-webkit-tap-highlight-color:transparent]",
              "focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-sheen-focus",
              // 44px tall hit area on touch screens without growing the legend.
              "sheen-hit",
            )}
          >
            <LegendKey color={item.color} kind={item.kind} dashed={item.dashed} hollow={off} pattern={item.pattern} />
            <span className={cn(off && "line-through decoration-1")}>{item.label}</span>
            {item.value !== undefined && <span className="font-semibold text-sheen-fg tabular-nums">{item.value}</span>}
          </button>
        );
      })}
      <ChartAnnouncer text={message} />
    </div>
  );
}

/**
 * The colour key for a series, drawn as SVG (not a CSS background) so it survives
 * forced-colors / Windows High Contrast, where it also gains a CanvasText outline.
 * `hollow` draws an outline only (a hidden series); `dashed` a dashed line (previous period); `pattern` hatches the swatch like the chart's `patterns`.
 *
 * Props: `color` (any CSS colour), `kind` ("rect" swatch by default, or "line"), `dashed` (a dashed line, for a previous period), `hollow` (outline only, for a hidden series) and `pattern` (hatch index 1 to 8, so the swatch matches a hatched series). Decorative: it is `aria-hidden`, the label next to it carries the meaning.
 *
 * @example
 * ```tsx
 * import { LegendKey } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <LegendKey color="var(--sheen-chart-1)" kind="line" dashed />
 *   );
 * }
 * ```
 *
 * @see /charts
 */
export function LegendKey({
  color,
  kind = "rect",
  dashed = false,
  hollow = false,
  pattern = 0,
}: {
  /** Any CSS color for the swatch, normally a `var(--sheen-chart-n)` token. */
  color: string;
  /** "line" draws a short stroke (line charts); "rect" draws a filled square (bars, areas). Default "rect". */
  kind?: "line" | "rect";
  /** Draw the stroke dashed, for a comparison or forecast series. */
  dashed?: boolean;
  /** Draw an outline only instead of a filled swatch. */
  hollow?: boolean;
  /** Hatch index (1 to 8) so the swatch matches a series drawn with `patterns`. Rect keys only. */
  pattern?: number;
}) {
  const patId = useId();
  const hatched = kind === "rect" && pattern > 0 && !hollow;
  return kind === "line" ? (
    <svg
      aria-hidden
      data-slot="legend-key"
      width={14}
      height={10}
      viewBox="0 0 14 10"
      className="shrink-0 forced-color-adjust-none"
    >
      <line
        x1={1}
        x2={13}
        y1={5}
        y2={5}
        stroke={color}
        strokeWidth={2.5}
        strokeLinecap="round"
        strokeDasharray={dashed ? "3 3" : undefined}
        strokeOpacity={hollow ? 0.45 : 1}
      />
    </svg>
  ) : (
    <svg
      aria-hidden
      data-slot="legend-key"
      width={10}
      height={10}
      viewBox="0 0 10 10"
      className="shrink-0 forced-color-adjust-none"
    >
      {hatched && <ChartPatternDefs id={patId} entries={[{ index: pattern, color }]} />}
      <rect
        x={hollow ? 1 : 0.5}
        y={hollow ? 1 : 0.5}
        width={hollow ? 8 : 9}
        height={hollow ? 8 : 9}
        rx={2.5}
        fill={hollow ? "none" : patternFill(hatched, patId, pattern, color)}
        fillOpacity={dashed ? 0.45 : 1}
        stroke={hollow ? color : undefined}
        strokeWidth={hollow ? 1.5 : 1}
        className={hollow ? undefined : "stroke-transparent forced-colors:stroke-[CanvasText]"}
      />
    </svg>
  );
}

/**
 * Builds the ChartLegend items for a list of series (colour by position, key shape `line` or `rect`).
 * Pure, but exported from a client module: call it from client code.
 */
export function seriesLegend(
  series: readonly ChartSeries[],
  kind: "line" | "rect",
  /** Hatch the swatches like the chart's `patterns` prop. Default: on from 4 series, as in the charts. */
  patterns?: boolean,
): LegendItem[] {
  const hatched = kind === "rect" && resolvePatterns(patterns, series.length);
  return series.map((s, i) => ({
    label: s.label,
    color: seriesColor(s, i),
    kind,
    key: s.key,
    pattern: hatched && i > 0 ? i : undefined,
  }));
}

/* ---------- Tooltip ---------- */

/** One row of a chart tooltip: label, formatted value, colour, key shape and whether the key is dashed. */
export type TooltipRow = { label: string; value: string; color: string; kind?: "line" | "rect"; dashed?: boolean };

/**
 * "glass": the standard glass-3 tooltip. "opaque": the same glass, but a near-solid fill so
 * dense chart text behind it never shows through (busy charts, small screens).
 */
export type TooltipSurface = "glass" | "opaque";

/** Classes + style for a chart tooltip surface (for charts that build their own tooltip). */
export function chartTooltipSurface(surface: TooltipSurface = "glass") {
  return {
    className: "glass-3",
    style:
      surface === "opaque"
        ? { backgroundColor: "color-mix(in oklab, var(--sheen-surface-solid) 94%, transparent)" }
        : undefined,
  } as const;
}

/**
 * Props of ChartTooltip: title, rows, the pointer position and container width, plus the `docked`,
 * surface and glide options.
 */
export type ChartTooltipProps = {
  /** The heading line: usually the category or date being read. */
  title: string;
  /** One line per series: a swatch, a label and the formatted value. */
  rows: TooltipRow[];
  /** Horizontal position of the pointer, in px from the left of the chart box. */
  x: number;
  /** Vertical position of the pointer, in px from the top of the chart box. */
  y: number;
  /** Width of the chart box in px, so the tooltip flips to stay inside it. */
  containerWidth: number;
  /** Pin the readout to the top of the chart as one line instead of following the pointer (used on narrow charts). */
  docked?: boolean;
  /** Surface style of the tooltip: glass or opaque. Default "glass". */
  surface?: TooltipSurface;
  /** Glide between points on the pointer spring (default) instead of jumping. */
  glide?: boolean;
  /** Extra lines under the values (e.g. an event marker at this point). */
  notes?: readonly string[];
};

/**
 * The event-marker diamond in front of a tooltip note. A rotated square, not a "◆" glyph: a
 * symbol the UI font lacks makes the browser search its fallback fonts the first time it is
 * laid out, a one-off stall that would land in the middle of the first hover.
 */
export function NoteMark() {
  return <span aria-hidden className="size-1.5 shrink-0 rotate-45 rounded-[1px] bg-current forced-color-adjust-none" />;
}

/**
 * Glass tooltip positioned inside the chart container. Values lead (strong), labels follow (muted).
 * `x` / `y` are in px relative to the container; it flips to stay inside, and glides from point
 * to point with a spring (transform only: it never triggers layout).
 * `docked`: a one-line readout pinned to the top of the chart instead (narrow charts, where a
 * floating tooltip would sit under the finger). The chart reserves TOOLTIP_DOCK_SPACE for it.
 * It is visual only: the chart announces the same values through ChartAnnouncer.
 *
 * Props: `title`, `rows` ({ label, value, color, kind?, dashed? }), `x` and `y` (px inside the chart container), `containerWidth`, `docked` (default false), `surface` ("glass" default or "opaque"), `glide` (default true) and `notes` (extra lines, e.g. event markers).
 * Accessibility: visual only (`aria-hidden`, no pointer events). The chart announces the same values through ChartAnnouncer, so keyboard and screen-reader users get them without the tooltip.
 * Glass and motion: one glass-3 surface; it glides on a spring, or jumps under reduced motion. Place it inside a `position: relative` container.
 *
 * @example
 * ```tsx
 * import { ChartTooltip } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <div style={{ position: "relative", width: 480, height: 160 }}>
 *       <ChartTooltip title="Mar" rows={[{ label: "Revenue", value: "$4.2k", color: "var(--sheen-chart-1)", kind: "line" }]} x={120} y={40} containerWidth={480} />
 *     </div>
 *   );
 * }
 * ```
 *
 * @see /charts
 */
export function ChartTooltip({
  title,
  rows,
  x,
  y,
  containerWidth,
  docked = false,
  surface = "glass",
  glide = true,
  notes,
}: ChartTooltipProps) {
  const reduced = useSheenReducedMotion();
  const springX = useSpring(x, followPointer);
  const springY = useSpring(y, followPointer);
  const still = reduced || !glide;
  useEffect(() => {
    if (still) {
      springX.jump(x);
      springY.jump(y);
    } else {
      springX.set(x);
      springY.set(y);
    }
  }, [x, y, still, springX, springY]);
  const look = chartTooltipSurface(surface);

  if (docked) {
    return (
      <div
        aria-hidden
        data-slot="chart-readout"
        className={cn(
          look.className,
          "pointer-events-none absolute inset-x-0 top-0 z-10 flex min-h-7.5 flex-wrap items-center gap-x-3 gap-y-0.5 rounded-sheen-md px-3 py-1.5 text-xs text-sheen-fg",
        )}
        style={look.style}
      >
        <span className="font-medium text-sheen-fg-muted">{title}</span>
        {rows.map((row, i) => (
          <span key={i} className="flex items-center gap-1.5 whitespace-nowrap">
            {row.color === "transparent" ? null : (
              <LegendKey color={row.color} kind={row.kind ?? "line"} dashed={row.dashed} />
            )}
            <span className="font-semibold text-sheen-fg tabular-nums">{row.value}</span>
            <span className="text-sheen-fg-muted">{row.label}</span>
          </span>
        ))}
        {notes?.map((n, i) => (
          <span key={`n${i}`} className="flex items-center gap-1.5 whitespace-nowrap text-sheen-fg-muted">
            <NoteMark />
            {n}
          </span>
        ))}
      </div>
    );
  }

  const flip = x > containerWidth - 180;
  return (
    <motion.div
      aria-hidden
      data-slot="chart-tooltip"
      className="pointer-events-none absolute top-0 left-0 z-10"
      style={{ x: still ? x : springX, y: still ? y : springY }}
    >
      <div
        className={cn(look.className, "min-w-36 rounded-sheen-md px-3 py-2.5 text-xs text-sheen-fg")}
        // The side flip glides (transform transition on the inner box) instead of jumping ~190px in one frame.
        style={{
          ...look.style,
          transform: `translate(${flip ? "calc(-100% - 14px)" : "14px"}, -50%)`,
          transition: "transform var(--sheen-duration-base) var(--sheen-ease-out)",
        }}
      >
        <p className="mb-1.5 font-medium text-sheen-fg-muted">{title}</p>
        <ul className="flex flex-col gap-1">
          {rows.map((row, i) => (
            <li key={i} className="flex items-center gap-2">
              {row.color === "transparent" ? (
                <span aria-hidden className="w-3.5 shrink-0" />
              ) : (
                <LegendKey color={row.color} kind={row.kind ?? "line"} dashed={row.dashed} />
              )}
              <span className="font-semibold text-sheen-fg tabular-nums">{row.value}</span>
              <span className="text-sheen-fg-muted">{row.label}</span>
            </li>
          ))}
        </ul>
        {notes && notes.length > 0 && (
          <ul className="mt-1.5 flex flex-col gap-0.5 border-t border-sheen-border pt-1.5 text-sheen-fg-muted">
            {notes.map((n, i) => (
              <li key={i} className="flex items-center gap-1.5">
                <NoteMark />
                {n}
              </li>
            ))}
          </ul>
        )}
      </div>
    </motion.div>
  );
}

/**
 * Screen-reader announcement of the active data point (charts are keyboard-navigable).
 *
 * Prop: `text` (the sentence to read; an empty string is silent). Renders a visually hidden `aria-live="polite"` region, so changes are read without moving focus. Charts feed it the active point when the keyboard moves it.
 *
 * @example
 * ```tsx
 * import { ChartAnnouncer } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <ChartAnnouncer text="March: revenue $4.2k" />
 *   );
 * }
 * ```
 *
 * @see /charts
 */
export function ChartAnnouncer({
  text,
}: {
  /** The message for the polite live region; screen readers read it when it changes. */
  text: string;
}) {
  return (
    <p data-slot="chart-announcer" aria-live="polite" aria-atomic="true" className="sr-only">
      {text}
    </p>
  );
}

"use client";

import { createContext, lazy, useCallback, useContext, useEffect, useMemo, useState } from "react";

/** Base UI's Menu is ~45 KB gzip: the download menu loads as its own chunk (see chart-export-menu.tsx). */
export const ChartExportMenu = lazy(() => import("../chart-export-menu"));

/* ====================================================================================
 * Series visibility: interactive legends (click hides a series, hover dims the others).
 * A ChartCard owns the state and shares it with the chart inside through context; charts
 * that support it (LineChart, AreaChart, BarChart, DonutChart) register, which turns the
 * card's legend into toggle buttons. Charts that don't register keep a static legend.
 * ==================================================================================== */

/**
 * The shared legend state of a ChartCard: hidden series, the highlighted series and the functions that
 * change them.
 */
export type ChartSeriesState = {
  /** Keys of the hidden series. */
  hidden: ReadonlySet<string>;
  /** Key of the series being pointed at in the legend (the others dim), or null. */
  highlighted: string | null;
  toggle: (key: string) => void;
  setHighlighted: (key: string | null) => void;
};

/** The shared series state plus the `register` call a series makes on mount. @internal */
export type SeriesContextValue = ChartSeriesState & { register: () => () => void };

/** Shares series visibility between a legend and its chart. @internal */
export const SeriesContext = createContext<SeriesContextValue | null>(null);
/** A stable empty set, so a default never changes identity. @internal */
export const EMPTY_SET: ReadonlySet<string> = new Set();

/**
 * Hidden / highlighted series state for building your own interactive legend + chart pair.
 *
 * Returns `{ hidden, highlighted, toggle, setHighlighted }`. `defaultHidden` lists the series keys hidden at first. A ChartCard does this for you; use the hook when the legend and the chart live in different parts of the page.
 * Not a component: no DOM, keyboard or screen-reader behaviour of its own (the legend you pair it with is a group of toggle buttons).
 *
 * @example
 * ```tsx
 * import { ChartLegend, LineChart, seriesLegend, useChartSeriesState } from "@sheenui/theme";
 *
 * const series = [
 *   { key: "a", label: "Organic" },
 *   { key: "b", label: "Paid" },
 * ];
 * const rows = [
 *   { m: "Jan", a: 4, b: 2 },
 *   { m: "Feb", a: 6, b: 3 },
 * ];
 *
 * function Pair() {
 *   const state = useChartSeriesState();
 *   return (
 *     <>
 *       <ChartLegend items={seriesLegend(series, "line")} hidden={state.hidden} onToggle={state.toggle} onHighlight={state.setHighlighted} />
 *       <LineChart data={rows} index="m" series={series} hiddenSeries={[...state.hidden]} highlightedSeries={state.highlighted} aria-label="Visits by channel" />
 *     </>
 *   );
 * }
 * ```
 *
 * @see /charts
 */
export function useChartSeriesState(defaultHidden: readonly string[] = []): ChartSeriesState {
  const [hidden, setHidden] = useState<ReadonlySet<string>>(() => new Set(defaultHidden));
  const [highlighted, setHighlighted] = useState<string | null>(null);
  const toggle = useCallback((key: string) => {
    setHidden((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }, []);
  return useMemo(() => ({ hidden, highlighted, toggle, setHighlighted }), [hidden, highlighted, toggle]);
}

/**
 * For chart authors: the series visibility to draw with. Explicit props win; otherwise the
 * enclosing ChartCard's legend state (and this chart registers itself, so the legend becomes
 * interactive). Pass `enabled: false` to opt out.
 *
 * Options: `hiddenSeries` (keys to hide; wins over the card), `highlightedSeries` (key to emphasise, or null) and `enabled` (default true; false ignores the card). Returns `{ hidden: ReadonlySet<string>, highlighted: string | null }`.
 * Not a component: no DOM, keyboard or screen-reader behaviour. Registering with the card is what turns its legend into toggle buttons.
 *
 * @example
 * ```tsx
 * import { useChartSeriesVisibility } from "@sheenui/theme";
 *
 * function MyChart({ hiddenSeries }: { hiddenSeries?: string[] }) {
 *   const { hidden, highlighted } = useChartSeriesVisibility({ hiddenSeries });
 *   return (
 *     <p>
 *       {hidden.size} hidden, {highlighted ?? "none"} highlighted
 *     </p>
 *   );
 * }
 * ```
 *
 * @see /charts
 */
export function useChartSeriesVisibility({
  hiddenSeries,
  highlightedSeries,
  enabled = true,
}: {
  hiddenSeries?: readonly string[];
  highlightedSeries?: string | null;
  enabled?: boolean;
} = {}) {
  const ctx = useContext(SeriesContext);
  const fromCard = enabled ? ctx : null;
  const register = fromCard?.register;
  useEffect(() => (register ? register() : undefined), [register]);
  // The joined keys are the identity, so a new array with the same keys doesn't re-render marks.
  const hiddenKey = hiddenSeries?.join("\u0001");
  const cardHidden = fromCard?.hidden;
  const hidden = useMemo<ReadonlySet<string>>(
    () => (hiddenKey !== undefined ? new Set(hiddenKey ? hiddenKey.split("\u0001") : []) : (cardHidden ?? EMPTY_SET)),
    [hiddenKey, cardHidden],
  );
  return {
    hidden,
    highlighted: highlightedSeries !== undefined ? highlightedSeries : (fromCard?.highlighted ?? null),
  };
}

